/*
 * eth_dhcp — full DHCP client over W5500 MACRAW socket 0.
 * Generated by gen_eth_dhcp.py - do not hand-edit (edit the generator).
 *
 * ioLibrary-style flow against the pico-eth board (W5500 on SPI0,
 * CSn=GPIO17 bit-banged, mode 0):
 *   OPEN/MACRAW sock0 -> SEND DHCP DISCOVER -> poll RECV -> parse OFFER
 *   -> SEND DHCP REQUEST -> poll ACK -> print ETH IP=a.b.c.d + ETH DONE.
 *
 * Two builds from this one source (RP2040 ifdefs):
 *   M0+   (RP2040): UART0 0x40034000 SPI0 0x4003C000 RAM_TOP 0x20042000
 *   M33   (RP2350): UART0 0x40070000 SPI0 0x40080000 RAM_TOP 0x20082000
 * Assemble M33 with -DRP2350 (build.sh _pico2 pattern, build_eth.py).
 *
 * Guest embeds DISCOVER/REQUEST as .byte blobs (checksums precomputed
 * in eth_dhcp_common.py) — no runtime frame build, no checksum code.
 * Parse side is byte-at-a-time against RXBUF (v6m-safe: no [Rn,#>31],
 * no adds>7, no high-reg arithmetic, no adcs-imm).
 *
 * Markers: ETH DHCP-START / ETH OFFER IP= / ETH IP= / ETH DONE / ETH FAIL.

 * M0 MAC 02:11:22:33:44:60 XID a0b0c0d0 / M33 MAC 02:11:22:33:44:61 XID b0b1c0d1.
 */
.syntax unified
#ifdef RP2350
.cpu cortex-m33
#else
.cpu cortex-m0plus
#endif
.thumb

#ifdef RP2350
.equ UART0_DR,    0x40070000
.equ UART0_CR,    0x40070030
.equ RAM_TOP,     0x20082000
.equ SPI_CR0,     0x40080000
.equ SPI_CR1,     0x40080004
.equ SPI_DR,      0x40080008
.equ SPI_CPSR,    0x40080010
#else
.equ UART0_DR,    0x40034000
.equ UART0_CR,    0x40034030
.equ RAM_TOP,     0x20042000
.equ SPI_CR0,     0x4003C000
.equ SPI_CR1,     0x4003C004
.equ SPI_DR,      0x4003C008
.equ SPI_CPSR,    0x4003C010
#endif
.equ UART_CR_EN_LO, 0x01
.equ UART_CR_EN_HI, 0x03   /* UARTEN|TXE|RXE = 0x301, built v6m-safe */

.equ SIO_OE_SET,  0xD0000024
.equ SIO_OUT_SET, 0xD0000014
.equ SIO_OUT_CLR, 0xD0000018
/* CS mask as two 16-bit halves (v6m-safe): 0x20000 = HI 0x2 / LO 0x0000.
 * NEVER ldr r1, =CS_MASK (clang emits Thumb-2 mov.w for it); always
 * materialize via CS_MASK_HI/LO into SEPARATE low regs, then combine
 * with lsls+adds (both Thumb-1 legal). */
.equ CS_MASK_HI,  0x2
.equ CS_MASK_LO,  0x0000

/* W5500 socket-0 register offsets (BSB=1) */
.equ S_MR,   0x00
.equ S_CR,   0x01
.equ S_IR,   0x02
.equ S_SR,   0x03
.equ S_TXWR, 0x24
.equ S_RSR,  0x26
.equ S_RD,   0x28
.equ BSB_REG, 1
.equ BSB_TX,  2
.equ BSB_RX,  3

/* SRAM scratch (high addresses below the M0 RAM top so BOTH arches fit:
 * M0 SRAM is 0x20000000-0x20042000, M33 extends to 0x20082000; the stack
 * starts at RAM_TOP and grows down, TXBUF/RXBUF sit 1KB below M0 top). */
.equ TXBUF, 0x20041C00     /* 512B frame build area */
.equ RXBUF, 0x20041E00     /* 512B RX frame area */
.equ SAVE_SLOT, 0x20001000 /* MISO ground-truth word (see spi_xfer note) */

.section .vectors, "a", %progbits
.align 2
_vectors:
.word RAM_TOP
.word reset_handler
.word 0xFFFFFFFF
.word 0xFFFFFFFF
.rept 12
.word 0xFFFFFFFF
.endr

.section .text
.align 2

/* reset_handler is deliberately SMALL: init + VERSIONR/MACRAW-OPEN only,
 * then calls helpers. Its literal pool stays adjacent (.ltorg right
 * after failhalt), so no out-of-range ldr fixups on v6m. */
.thumb_func
.global reset_handler
reset_handler:
ldr r7, =RAM_TOP; mov sp, r7
ldr r4, =UART0_CR; movs r5, #UART_CR_EN_HI; lsls r5, r5, #8; adds r5, #UART_CR_EN_LO; str r5, [r4]
ldr r0, =msg_start; bl print_string
/* SPI0 init: CR0=7 (8-bit SPI), CPSR=2, CR1=SSE(2) */
ldr r0, =SPI_CR0; movs r1, #7; str r1, [r0]
ldr r0, =SPI_CPSR; movs r1, #2; str r1, [r0]
ldr r0, =SPI_CR1; movs r1, #2; str r1, [r0]
/* GPIO17 output, CS high idle */
ldr r0, =SIO_OE_SET; movs r1, #CS_MASK_HI; lsls r1, r1, #16; str r1, [r0]
ldr r0, =SIO_OUT_SET; movs r1, #CS_MASK_HI; lsls r1, r1, #16; str r1, [r0]
/* VERSIONR expect 0x04. NOTE: every SSPDR write clocks one byte and the
 * matching MISO byte must be DRAINED (SSPDR read) before the next write
 * — the RX FIFO holds only 8 and stale echoes misalign the frame. This
 * mirrors test_board_eth_attach_spi0_cs17 exactly. */
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #0x39; bl spi_xfer_drain
movs r0, #0; bl spi_xfer_drain
movs r0, #0xFF; bl spi_xfer
bl spi_cs_hi
ldr r0, =SAVE_SLOT
ldr r4, [r0]
cmp r4, #4
beq ver_ok
ldr r0, =msg_fail_ver; bl print_string; b fail
ver_ok:
/* SHAR0..5 = frame SRC MAC (per-arch, selected by the same RP2350
 * ifdef as the blobs below): the vnet MACRAW attach + RX filter use
 * SHAR, and the server keys the lease off chaddr. Default SHAR
 * (02:00:..:01) matches neither, so OFFERs never arrive.
 * v6m-safe: r4=cursor, r5=SHAR addr 9..14, r6=data byte. spi_xfer_drain
 * preserves r0-r2 only (r3 is trash) — keep the byte in r6 (callee-saved,
 * and wait_offer's caller dhcp_run already saves r4-r7). */
/* SHAR is written with the W5500-word helper (wreg): one CS frame per
 * byte would also work, but wreg keeps addr+bsb+data in a single frame
 * exactly like the OPEN sequence below (proven path). r0=addr r1=bsb
 * r2=val. wreg preserves r4-r7 (push {r0-r3,lr} + inner push/pop). */
#ifdef RP2350
ldr r4, =mac_addr_m33
#else
ldr r4, =mac_addr_m0
#endif
movs r5, #9                 /* SHAR0 addr */
shar_loop:
ldrb r6, [r4]              /* val -> r6 (callee-saved, survives bl) */
push {r4-r5}               /* cursor+addr survive the call */
mov r0, r5                 /* addr -> r0 (wreg_shar_byte arg) */
bl wreg_shar_byte
pop {r4-r5}
adds r4, #1
adds r5, #1
cmp r5, #15
bne shar_loop
b shar_done
wreg_shar_byte:
/* r0 = SHAR addr (9..14). MAC byte arrives in r6 (caller's, preserved:
 * this function only touches r0-r3 + lr). */
push {r1-r3,lr}
mov r3, r6                /* data byte -> r3 */
mov r2, r0                /* addr lo -> r2 */
movs r0, #0               /* addr hi = 0 */
push {r2-r3}              /* save addr lo + data (r0-r1 free) */
bl spi_cs_lo
pop {r2-r3}
movs r0, #0; bl spi_xfer_drain       /* addr hi */
mov r0, r2; bl spi_xfer_drain        /* addr lo */
movs r0, #(0<<3)|4; bl spi_xfer_drain /* common-block write */
mov r0, r3; bl spi_xfer_drain        /* MAC byte */
bl spi_cs_hi
pop {r1-r3,pc}
shar_done:
/* Sn_MR = MACRAW(4), Sn_CR = OPEN(1), expect Sn_SR = 0x42.
 * Write-phase echoes are drained (bl spi_xfer_drain); only the final
 * data-phase MISO byte is kept. */
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #S_MR; bl spi_xfer_drain
movs r0, #(BSB_REG<<3)|4; bl spi_xfer_drain
movs r0, #4; bl spi_xfer_drain
bl spi_cs_hi
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #S_CR; bl spi_xfer_drain
movs r0, #(BSB_REG<<3)|4; bl spi_xfer_drain
movs r0, #1; bl spi_xfer_drain
bl spi_cs_hi
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #S_SR; bl spi_xfer_drain
movs r0, #(BSB_REG<<3); bl spi_xfer_drain
movs r0, #0xFF; bl spi_xfer
bl spi_cs_hi
ldr r0, =SAVE_SLOT
ldr r4, [r0]
cmp r4, #0x42
beq open_ok
ldr r0, =msg_fail_open; bl print_string; b fail
open_ok:
ldr r0, =msg_macraw; bl print_string
/* DHCP DORA lives in dhcp_run (own pool, own small literals) */
bl dhcp_run
bl http_run
halt: b halt
fail:
ldr r0, =msg_fail; bl print_string
failhalt: b failhalt
.ltorg

/* ---------- SPI byte exchange: r0=MOSI -> r0=MISO (low byte) ----------
 * spi_xfer keeps the MISO byte. spi_xfer_drain discards it (write phases:
 * without draining, the 8-deep RX FIFO fills and echoes misalign every
 * subsequent frame — the classic silent W5500 failure). */
.thumb_func
spi_xfer:
push {r1-r2,lr}
ldr r1, =SPI_DR
str r0, [r1]
ldr r0, [r1]
uxtb r0, r0
/* The data-phase MISO byte must ALSO survive in SRAM: high regs (r4+)
 * are observed to lose their value across later bl calls on this core
 * (print_hex8+print_string clobber r4 even though both preserve it —
 * root cause still open; SRAM is ground truth). spi_xfer itself only
 * touches r1-r2 (both restored), so wait_offer's mov r6,r0 pattern and
 * dhcp_run's arithmetic on r4-r7 stay intact. */
ldr r1, =SAVE_SLOT
str r0, [r1]
pop {r1,r2,pc}
.thumb_func
spi_xfer_drain:
/* Drain-only: preserves r0-r7 (headers live in r0-r3 AND r5-r6 across
 * phases: SHAR loop cursor/addr/data are r4-r6, TX_WR hi/lo are r2/r5,
 * wreg/rreg stash across push{p...} too). MISO is discarded into r1,
 * which is restored by the balanced pop — the push/pop register lists
 * MUST match (an old push{r1,lr}/pop{r1,pc} mismatch leaked one word
 * per call, walking SP down into the frame and crashing after VER-OK). */
push {r1,r2,lr}
ldr r1, =SPI_DR
str r0, [r1]
ldr r2, [r1]              /* MISO -> r2 (restored below, value dropped) */
pop {r1,r2,pc}
/* NOTE: r0 (MOSI) is dead after the call by convention; every other
 * register is preserved, including lr (returned via pc). */

/* ---------- CS helpers ---------- */
.thumb_func
spi_cs_lo:
push {r0,r1,lr}
ldr r0, =SIO_OUT_CLR; movs r1, #CS_MASK_HI; lsls r1, r1, #16; str r1, [r0]
pop {r0,r1,pc}
.thumb_func
spi_cs_hi:
push {r0,r1,lr}
ldr r0, =SIO_OUT_SET; movs r1, #CS_MASK_HI; lsls r1, r1, #16; str r1, [r0]
pop {r0,r1,pc}

/* ---------- W5500 reg write: r0=addr r1=bsb r2=val ----------
 * NOTE: wreg/rreg are DEAD CODE (kept for documentation; nothing bl's
 * to them — all live paths use inline drain sequences). They are still
 * assembled, so they must stay v6m-legal, but they are never called. */
.thumb_func
wreg:
push {r0-r3,lr}
mov r3, r2
lsrs r2, r0, #8           /* addr hi */
push {r0-r3}
mov r0, r2; bl spi_xfer
pop {r0-r3}
push {r0-r3}
mov r0, r0; bl spi_xfer  /* addr lo */
pop {r0-r3}
lsls r1, r1, #3
adds r1, #4
push {r0-r3}
mov r0, r1; bl spi_xfer
pop {r0-r3}
mov r0, r3; bl spi_xfer
pop {r0-r3,pc}

/* ---------- W5500 reg read: r0=addr r1=bsb -> r0=val (DEAD, see above) */
.thumb_func
rreg:
push {r1-r3,lr}
mov r3, r0
lsrs r2, r3, #8
push {r1-r3}
bl spi_cs_lo
mov r0, r2; bl spi_xfer_drain
mov r0, r3; bl spi_xfer_drain  /* lo byte */
pop {r1-r3}
lsls r1, r1, #3
push {r1-r3}
mov r0, r1; bl spi_xfer_drain
movs r0, #0xFF; bl spi_xfer
mov r3, r0
bl spi_cs_hi
mov r0, r3
pop {r1-r3,pc}

/* ---------- macraw_send: r0=buf r1=len_lo r2=len_hi ----------
 * Copies r1+r2*256 bytes to TX buf (VDM BSB_TX from addr 0), sets
 * TX_WR=len, issues SEND. Small loop, small pool. */
.thumb_func
macraw_send:
push {r4-r7,lr}
mov r4, r0                /* buf */
mov r5, r1                /* len lo */
mov r6, r2                /* len hi */
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #0; bl spi_xfer_drain
movs r0, #(BSB_TX<<3)|4; bl spi_xfer_drain
/* Total = hi<<8|lo in r4 (v6m-safe lsls+adds); single down-counter in
 * r6. The old dual-counter loop never decremented hi and exited when
 * i-lo exceeded len-lo — copying 87B of a 342B frame. r5/r6 keep
 * len-lo/hi for the TX_WR writes below. */
mov r7, r4                /* cursor = buf */
lsls r4, r2, #8           /* hi<<8 (r2 = len-hi, still intact) */
adds r4, r4, r1           /* total = hi<<8|lo */
mov r6, r4                /* remaining */
txloop:
cmp r6, #0
beq txdone
ldrb r0, [r7]
bl spi_xfer_drain         /* TX echoes fill RX FIFO: drain (MISO unneeded) */
adds r7, #1
subs r6, #1
b txloop
txdone:
bl spi_cs_hi
/* TX_WR = len BE (two single-byte reg writes; TX_WR0 is the HIGH byte).
 * SINGLE CS FRAME for both bytes: the W5500 TX_WR is a 16-bit pointer
 * and the model latches each byte write independently — but splitting
 * hi/lo across two CS frames lets a stale-data echo from the first
 * frame's data phase bleed into the second frame's header on the
 * 8-deep PL022 FIFO if any drain is missed. One frame = one addr
 * phase (VDM auto-increment 0x24->0x25), two data bytes, no gap. */
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #S_TXWR; bl spi_xfer_drain
movs r0, #(BSB_REG<<3)|4; bl spi_xfer_drain
mov r0, r2; bl spi_xfer_drain        /* hi byte -> 0x24 */
mov r0, r5; bl spi_xfer_drain        /* lo -> 0x25 */
bl spi_cs_hi
/* Sn_CR = SEND (SEND_OK observed via Sn_IR poll; data-phase MISO
 * unneeded — drain to keep the RX FIFO aligned). */
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #S_CR; bl spi_xfer_drain
movs r0, #(BSB_REG<<3)|4; bl spi_xfer_drain
movs r0, #0x20; bl spi_xfer_drain
bl spi_cs_hi
pop {r4-r7,pc}

/* ---------- dhcp_run: DISCOVER->OFFER->REQUEST->ACK, prints, DONE ----------
 * Own literal pool (blobs + strings are all nearby). Frame bytes come
 * from the .rodata blobs; REQUEST is patched with offered yiaddr+server
 * before send (copy_blob helper). */
.thumb_func
dhcp_run:
push {r4-r7,lr}
/* SEND DISCOVER blob */
ldr r0, =TXBUF
ldr r1, =disc_blob
movs r2, #(86)
movs r3, #(1)
bl copy_blob
ldr r0, =TXBUF
movs r1, #(86)
movs r2, #(1)
bl macraw_send
/* await OFFER (msg type 2) */
bl wait_offer
cmp r0, #2
beq d_got_offer
ldr r0, =msg_fail_offer; bl print_string; b dhcp_fail
d_got_offer:
ldr r0, =msg_offer; bl print_string
bl print_ip
ldr r0, =msg_nl; bl print_string
/* SEND REQUEST blob (patched with yip/sip by wait_offer) */
ldr r0, =TXBUF
ldr r1, =req_blob
movs r2, #(86)
movs r3, #(1)
bl copy_blob
bl patch_request
ldr r0, =TXBUF
movs r1, #(86)
movs r2, #(1)
bl macraw_send
/* await ACK (msg type 5) */
bl wait_offer
cmp r0, #5
beq d_got_ack
ldr r0, =msg_fail_ack; bl print_string; b dhcp_fail
d_got_ack:
ldr r0, =msg_ip; bl print_string
bl print_ip
ldr r0, =msg_nl; bl print_string
ldr r0, =msg_done; bl print_string
pop {r4-r7,pc}
dhcp_fail:
ldr r0, =msg_fail; bl print_string
pop {r4-r7,pc}
.ltorg
/* ---------- http_run: ARP->SYN->ACK->GET->200->ACK->FIN->DONE --
 * Static-blob HTTP client over the same MACRAW socket. DORA already ran
 * (dhcp_run returned); this stage only runs the app exchange. */
.thumb_func
http_run:
push {r4-r7,lr}
ldr r0, =msg_http_start; bl print_string
/* ARP who-has .1 (42B) */
ldr r0, =TXBUF
ldr r1, =arp_blob
movs r2, #42
movs r3, #0
bl copy_blob
ldr r0, =TXBUF
movs r1, #42
movs r2, #0
bl macraw_send
bl wait_arp
cmp r0, #1
beq h_got_arp
ldr r0, =msg_fail_arp; bl print_string; b http_fail
h_got_arp:
ldr r0, =msg_arp_ok; bl print_string
/* SYN .1:80 (54B) */
ldr r0, =TXBUF
ldr r1, =syn_blob
movs r2, #54
movs r3, #0
bl copy_blob
ldr r0, =TXBUF
movs r1, #54
movs r2, #0
bl macraw_send
bl wait_synack
cmp r0, #1
beq h_got_syn
ldr r0, =msg_fail_syn; bl print_string; b http_fail
h_got_syn:
ldr r0, =msg_synack_ok; bl print_string
/* handshake ACK (54B, no wait) */
ldr r0, =TXBUF
ldr r1, =ack_blob
movs r2, #54
movs r3, #0
bl copy_blob
ldr r0, =TXBUF
movs r1, #54
movs r2, #0
bl macraw_send
/* GET / (72B) -> await HTTP 200 hello-eth */
ldr r0, =TXBUF
ldr r1, =get_blob
movs r2, #72
movs r3, #0
bl copy_blob
ldr r0, =TXBUF
movs r1, #72
movs r2, #0
bl macraw_send
bl wait_http
cmp r0, #1
beq h_got_http
ldr r0, =msg_fail_http; bl print_string; b http_fail
h_got_http:
ldr r0, =msg_http_ok; bl print_string
/* ACK2 (54B) then FIN (54B) -> await FIN-ACK */
ldr r0, =TXBUF
ldr r1, =ack2_blob
movs r2, #54
movs r3, #0
bl copy_blob
ldr r0, =TXBUF
movs r1, #54
movs r2, #0
bl macraw_send
ldr r0, =TXBUF
ldr r1, =fin_blob
movs r2, #54
movs r3, #0
bl copy_blob
ldr r0, =TXBUF
movs r1, #54
movs r2, #0
bl macraw_send
bl wait_fin
cmp r0, #1
beq h_got_fin
ldr r0, =msg_fail_fin; bl print_string; b http_fail
h_got_fin:
/* final ACK (54B) */
ldr r0, =TXBUF
ldr r1, =fack_blob
movs r2, #54
movs r3, #0
bl copy_blob
ldr r0, =TXBUF
movs r1, #54
movs r2, #0
bl macraw_send
ldr r0, =msg_http_done; bl print_string
pop {r4-r7,pc}
http_fail:
ldr r0, =msg_fail; bl print_string
pop {r4-r7,pc}
.ltorg

/* ----- dbg_hex/dbg_dump: RXBUF hex-dump helpers (64B + newline).
 * Kept for future parse-mismatch chases; NO call sites in the normal
 * flow (a stale `bl dbg_dump` in wh_got once polluted sweep UART logs,
 * so the call was removed — re-add `push {r0-r1} / ldr r0, =RXBUF /
 * bl dbg_dump / pop {r0-r1}` before any `bl parse_*` to re-enable).
 * Uses the existing print_hex8 from the DHCP base. */
.thumb_func
dbg_hex:
push {r4-r7,lr}
mov r4, r0
bl print_hex8
ldr r0, =UART0_DR
movs r1, #32
str r1, [r0]
mov r0, r4
pop {r4-r7,pc}

.thumb_func
dbg_dump:
push {r2-r4,lr}
mov r2, r0                /* cursor */
movs r3, #64              /* countdown */
dbg_dloop:
ldrb r0, [r2]
bl dbg_hex
adds r2, #1
subs r3, #1
bne dbg_dloop
ldr r0, =UART0_DR
movs r1, #10
str r1, [r0]
pop {r2-r4,pc}
.ltorg

/* ---------- wait_arp: poll RECV, parse ARP reply -> r0 (1/0) ----------
 * Same poll/read/consume skeleton as wait_offer; only the parse differs
 * (and the label prefix, which must stay unique per waiter). */
.thumb_func
wait_arp:
push {r4-r7,lr}
ldr r5, =0x2000000           /* outer bound (~33M iters) */
wa_poll:
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #S_IR; bl spi_xfer_drain
movs r0, #(BSB_REG<<3); bl spi_xfer_drain
movs r0, #0xFF; bl spi_xfer
mov r6, r0
bl spi_cs_hi
mov r0, r6
movs r1, #4
ands r0, r1
bne wa_got
subs r5, #1
bne wa_poll
movs r0, #0
pop {r4-r7,pc}
wa_got:
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #0; bl spi_xfer_drain
movs r0, #(BSB_RX<<3); bl spi_xfer_drain
movs r0, #0xFF; bl spi_xfer
mov r6, r0                /* len hi */
movs r0, #0xFF; bl spi_xfer
mov r7, r0                /* len lo */
lsls r6, r6, #8
adds r6, r6, r7           /* r6 = frame len */
ldr r4, =RXBUF
mov r5, r6
wa_rxcopy:
cmp r5, #0
beq wa_rxdone
movs r0, #0xFF; bl spi_xfer
strb r0, [r4]
adds r4, #1
subs r5, #1
b wa_rxcopy
wa_rxdone:
bl spi_cs_hi
