/* ---------- wait_offer: poll RECV, parse msg type -> r0 (2/5/0) -------
 * Bounded poll of Sn_IR RECV; reads one RX frame (len prefix + frame)
 * into RXBUF; validates ethertype/bootp magic/xid; saves yiaddr+server;
 * returns DHCP msg type (opt 53) or 0 on timeout/mismatch (then the
 * caller retries until its own bound expires).
 * NOTE: Sn_IR is polled WITHOUT dropping CS between header bytes and
 * the data byte (single CS frame; CS-hi between header/data would still
 * work on VDM but wastes polls). r6 holds the RECV bit in r0-safe regs
 * (r0 dies in spi_xfer_drain — MISO returns in r0 only from spi_xfer). */
.thumb_func
wait_offer:
push {r4-r7,lr}
ldr r5, =0x2000000           /* outer bound (~33M iters) */
wo_poll:
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #S_IR; bl spi_xfer_drain
movs r0, #(BSB_REG<<3); bl spi_xfer_drain
movs r0, #0xFF; bl spi_xfer
mov r6, r0
bl spi_cs_hi
mov r0, r6
movs r1, #4
ands r0, r1
bne wo_got
subs r5, #1
bne wo_poll
movs r0, #0
pop {r4-r7,pc}
wo_got:
/* read RX buffer start: len_hi,len_lo then frame bytes to RXBUF.
 * Header-phase echoes drained; len bytes KEPT (need them); frame bytes
 * KEPT (strb to RXBUF). W5500 prefix INCLUDES its own 2 bytes
 * (hardware semantics: stored = frame_len + 2), so subtract 2 for the
 * payload count. */
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #0; bl spi_xfer_drain
movs r0, #(BSB_RX<<3); bl spi_xfer_drain
movs r0, #0xFF; bl spi_xfer
mov r6, r0                /* len hi */
movs r0, #0xFF; bl spi_xfer
mov r7, r0                /* len lo */
lsls r6, r6, #8
adds r6, r6, r7           /* r6 = stored len (frame + 2) */
subs r6, #2               /* r6 = frame len */
ldr r4, =RXBUF
mov r5, r6
wo_rxcopy:
cmp r5, #0
beq wo_rxdone
movs r0, #0xFF; bl spi_xfer
strb r0, [r4]               /* KEEP MISO: model returns data, not echo */
adds r4, #1
subs r5, #1
b wo_rxcopy
wo_rxdone:
bl spi_cs_hi
/* Sn_CR = RECV (consume one frame; data-phase MISO unneeded — drain) */
bl spi_cs_lo
movs r0, #0; bl spi_xfer_drain
movs r0, #S_CR; bl spi_xfer_drain
movs r0, #(BSB_REG<<3)|4; bl spi_xfer_drain
movs r0, #0x40; bl spi_xfer_drain
bl spi_cs_hi
bl parse_offer            /* r0 = msg type or 0 */
cmp r0, #0
bne wo_done
/* not ours: re-poll budget (v6m-safe, no T2 mov.w) then give up */
ldr r5, =0x1000000           /* re-poll budget */
b wo_poll
wo_done:
pop {r4-r7,pc}
.ltorg

/* ---------- parse_offer: RXBUF frame -> yiaddr/sip, r0 = msgtype/0 ----
 * Checks ethertype 0800, bootp magic, xid; saves yiaddr->yip_addr and
 * opt54->sip_addr; walks options for opt53. Byte-at-a-time, v6m-safe. */
.thumb_func
parse_offer:
push {r4-r7,lr}
ldr r0, =RXBUF
adds r0, #7
adds r0, #5               /* r0 = RXBUF+12 ethertype */
ldrb r1, [r0]
cmp r1, #8
bne po_no
adds r0, #1
ldrb r1, [r0]
cmp r1, #0
bne po_no
adds r0, #1               /* r0 = RXBUF+14 IP */
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #2
adds r0, #2               /* r0 = bootp+4 xid */
ldrb r1, [r0]
#ifdef RP2350
cmp r1, #0xB0
#else
cmp r1, #0xA0
#endif
bne po_no
adds r0, #1
ldrb r1, [r0]
#ifdef RP2350
cmp r1, #0xB1
#else
cmp r1, #0xB0
#endif
bne po_no
adds r0, #7
adds r0, #4               /* r0 = bootp+16 yiaddr */
ldr r1, =yip_addr
ldrb r2, [r0]; strb r2, [r1]
adds r0, #1
adds r1, #1
ldrb r2, [r0]; strb r2, [r1]
adds r0, #1
adds r1, #1
ldrb r2, [r0]; strb r2, [r1]
adds r0, #1
adds r1, #1
ldrb r2, [r0]; strb r2, [r1]
/* r0 = bootp+19 -> magic at bootp+236 (+217) */
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7
adds r0, #7               /* +217 = bootp+236 */
ldrb r1, [r0]
cmp r1, #99
bne po_no
adds r0, #1
ldrb r1, [r0]
cmp r1, #130
bne po_no
adds r0, #3               /* bootp+240 options */
ldr r1, =sip_addr
movs r2, #0               /* msg type */
po_optloop:
ldrb r3, [r0]
cmp r3, #255
beq po_optdone
cmp r3, #53
bne po_opt_next
adds r0, #2
ldrb r2, [r0]
subs r0, #2
b po_opt_adv
po_opt_next:
cmp r3, #54
bne po_opt_adv
adds r0, #2
ldrb r3, [r0]; strb r3, [r1]
adds r0, #1
adds r1, #1
ldrb r3, [r0]; strb r3, [r1]
adds r0, #1
adds r1, #1
ldrb r3, [r0]; strb r3, [r1]
adds r0, #1
adds r1, #1
ldrb r3, [r0]; strb r3, [r1]
subs r0, #3
subs r1, #3
b po_opt_adv2
po_opt_adv:
ldrb r3, [r0, #1]
adds r0, #2
adds r0, r0, r3
b po_optloop
po_opt_adv2:
ldrb r3, [r0, #1]
adds r0, #2
adds r0, r0, r3
b po_optloop
po_optdone:
mov r0, r2
pop {r4-r7,pc}
po_no:
movs r0, #0
pop {r4-r7,pc}
.ltorg

/* print_hex8: r0 = byte -> 2 hex digits. Lives with the other print
 * helpers (pool-local); the early .ltorg after reset covers reset's own
 * literals. Clobbers r1,r2. */
.thumb_func
print_hex8:
push {r1,r2,lr}
mov r1, r0
lsrs r0, r1, #4
cmp r0, #10
blo hex8_hi
adds r0, #7
hex8_hi:
adds r0, #0x30
ldr r2, =UART0_DR
str r0, [r2]
movs r0, r1
movs r1, #15
ands r0, r1
cmp r0, #10
blo hex8_lo
adds r0, #7
hex8_lo:
adds r0, #0x30
str r0, [r2]
pop {r1,r2,pc}

/* ---------- print helpers ---------- */
.thumb_func
print_string:
push {r1-r3,lr}
mov r1, r0
ldr r2, =UART0_DR
ps_loop:
ldrb r3, [r1]
cmp r3, #0
beq ps_done
str r3, [r2]
adds r1, #1
b ps_loop
ps_done:
pop {r1-r3,pc}

.thumb_func
print_ip:                 /* prints yip_addr as a.b.c.d (no newline) */
push {r4-r6,lr}
ldr r4, =yip_addr
movs r5, #4
ip_oct:
ldrb r0, [r4]
bl print_u8
subs r5, #1
beq ip_end
movs r0, #46              /* '.' */
ldr r1, =UART0_DR
str r0, [r1]
adds r4, #1
b ip_oct
ip_end:
pop {r4-r6,pc}

.thumb_func
print_u8:                 /* r0 = 0..255 -> decimal, no leading zeros */
push {r4-r6,lr}
mov r4, r0
movs r6, #0
movs r5, #100
bl print_digit
movs r5, #10
bl print_digit
movs r5, #1
bl print_digit
pop {r4-r6,pc}

.thumb_func
print_digit:              /* r4=val r5=div r6=printed-flag; digit via subtract */
push {r0-r2,lr}
mov r0, r4
mov r1, r5
movs r2, #0
dloop:
cmp r0, r1
blo ddone
subs r0, r0, r1
adds r2, #1
b dloop
ddone:
mov r4, r0
cmp r5, #1
beq dshow
cmp r2, #0
bne dshow
cmp r6, #1
beq dshow_zero
b dend
dshow_zero:
movs r2, #0
dshow:
adds r2, #48
ldr r0, =UART0_DR
str r2, [r0]
movs r6, #1
b dend
dend:
pop {r0-r2,pc}

.ltorg

