/* SRAM state (NOT .bss/.data: the raw .bin image has no startup copier
 * and flash is not writable — state lives at fixed SRAM addresses valid
 * on BOTH arches: M0 SRAM is 0x20000000-0x20042000, M33 0x20082000 top;
 * low 0x20000000+256 is free RAM on both; stack starts at RAM_TOP). */
.equ YIP_ADDR, 0x20000100
.equ SIP_ADDR, 0x20000104
.equ yip_addr, YIP_ADDR
.equ sip_addr, SIP_ADDR
